ear-gradient(90deg,#2563eb,#7c3aed);color:#fff;padding:12px 18px}.grid{display:grid;grid-template-columns:1.25fr .75fr;gap:15px;margin-top:17px}.panel{background:var(--panel);border:1px solid var(--line);border-radius:17px;padding:17px}.panel h2{font-size:15px;margin:0 0 15px}.empty{color:#6f849a;padding:24px 8px;text-align:center}.plan{margin:0;padding:0;list-style:none}.plan li{padding:12px 0;border-bottom:1px solid #1c3045}.plan li:last-child{border:0}.plan b{display:block;margin-bottom:4px}.muted{color:var(--muted)}.response{white-space:pre-wrap;line-height:1.55}.agent{display:flex;justify-content:space-between;gap:10px;padding:11px 0;border-bottom:1px solid #1c3045}.agent:last-child{border:0}.agent-state{font-size:12px;color:var(--muted)}.agent-state.planned{color:var(--blue)}.agent-state.active{color:var(--green);font-weight:900}.connector{display:flex;justify-content:space-between;gap:12px;padding:10px 0;border-bottom:1px solid #1c3045}.connector:last-child{border:0}.badge{font-size:12px;font-weight:800}.badge.ok{color:var(--green)}.badge.warn{color:var(--amber)}.badge.bad{color:var(--red)}.history{max-height:220px;overflow:auto}.history-item{padding:10px 0;border-bottom:1px solid #1c3045;font-size:13px}.history-item:last-child{border:0}.approval{display:flex;gap:8px}.notice{margin-top:14px;color:#8094a9;font-size:12px}.errorbox{display:none;margin-top:12px;border:1px solid #71303d;background:#2d1119;color:#ffb2be;padding:11px;border-radius:10px}.errorbox.show{display:block}.deliverable-actions{display:flex;gap:8px;margin-top:14px;flex-wrap:wrap}.deliverable-actions .btn{padding:9px 12px}.task-row.failed{color:var(--red);border-color:var(--red)}.task-row.blocked{color:var(--amber);border-color:var(--amber)}@media(max-width:850px){.shell{display:block}.side{padding:14px 16px;border-right:0;border-bottom:1px solid var(--line)}.spectrum{margin:8px 0 12px}.nav{display:flex;overflow:auto}.nav a{white-space:nowrap}.main{padding:18px 14px 90px}.grid{grid-template-columns:1fr}.top{align-items:flex-start}.top h1{font-size:23px}.composer textarea{font-size:16px;min-height:135px}.row{align-items:stretch;flex-direction:column}.actions{width:100%}.actions .btn{flex:1}.status{white-space:nowrap}}
