<section class="composer"><textarea id="command" maxlength="4000" aria-label="Business command" placeholder="Tell Rainbow AI what business outcome you want."></textarea><div class="row"><div class="muted" id="charCount">0 / 4000</div><div class="actions"><label class="auto-toggle"><input id="autoMode" type="checkbox"> Auto Mode</label><button class="btn" id="voice" type="button">Voice Input</button><button class="btn primary" id="send" type="button">Send Command</button></div></div><div class="errorbox" id="errorBox" role="alert"></div></section>
<div class="grid">
