<section class="panel"><h2>Connector status</h2><div class="connector"><span>OpenAI API</span><span class="badge warn" id="openaiConnector">Checking</span></div><div class="connector"><span>Admin security</span><span class="badge warn" id="adminConnector">Checking</span></div><div class="connector"><span>Meta Ads</span><span class="badge warn" id="metaConnector">Checking</span></div><div class="connector"><span>WhatsApp</span><span class="badge warn" id="whatsappConnector">Checking</span></div><div class="connector"><span>CRM</span><span class="badge warn" id="crmConnector">Checking</span></div></section>
