<script>
const csrf=<?=json_encode($csrf, JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;
const command=document.getElementById('command'),send=document.getElementById('send'),voice=document.getElementById('voice'),autoMode=document.getElementById('autoMode'),taskTracker=document.getElementById('taskTracker'),plan=document.getElementById('plan'),response=document.getElementById('response'),copyOutput=document.getElementById('copyOutput'),continueOutput=document.getElementById('continueOutput'),agents=document.getElementById('agents'),executionDetails=document.getElementById('executionDetails'),errorBox=document.getElementById('errorBox'),history=document.getElementById('history'),apiStatus=document.getElementById('apiStatus'),openaiConnector=document.getElementById('openaiConnector'),adminConnector=document.getElementById('adminConnector'),metaConnector=document.getElementById('metaConnector'),whatsappConnector=document.getElementById('whatsappConnector'),crmConnector=document.getElementById('crmConnector'),charCount=document.getElementById('charCount');
let currentProjectName='';
function setStatus(text,kind){apiStatus.textContent=text;apiStatus.className='status '+kind}function badge(el,text,kind){el.textContent=text;el.className='badge '+kind}function error(message){errorBox.textContent=message;errorBox.classList.toggle('show',!!message)}function addHistory(text,state){if(history.querySelector('.empty'))history.innerHTML='';const row=document.createElement('div');row.className='history-item';row.textContent=new Date().toLocaleTimeString()+' — '+state+': '+text.slice(0,120);history.prepend(row)}
function renderResult(d){const runs=Array.isArray(d.executions)?d.executions:[];const completed=runs.filter(x=>x.status==='completed'&&x.output);currentProjectName=d.context?.project_name||currentProjectName;response.className=completed.length?'response':'empty';response.textContent=completed.length?completed.map(x=>x.output).join('\n\n---\n\n'):(d.state==='blocked_for_approval'?'Action blocked pending approval. No external action was executed.':'No deliverable generated.');copyOutput.disabled=!completed.length;continueOutput.disabled=!completed.length;plan.innerHTML='';(d.plan.steps||[]).forEach(s=>{const li=document.createElement('li');const b=document.createElement('b');b.textContent='Step '+s.step_number+' — '+s.agent;const x=document.createElement('div');x.className='muted';x.textContent=s.action;li.append(b,x);plan.appendChild(li)});agents.innerHTML='';const owner=document.createElement('div');owner.className='agent';owner.innerHTML='<span>Business Owner</span><span class="agent-state active">completed</span>';agents.appendChild(owner);runs.forEach(x=>{const row=document.createElement('div');row.className='agent';const n=document.createElement('span');n.textContent=x.agent;const st=document.createElement('span');st.className='agent-state '+(x.status==='completed'?'active':'planned');st.textContent=x.status;row.append(n,st);agents.appendChild(row)});executionDetails.className='response';executionDetails.textContent=runs.length?runs.map(x=>'Execution Status: '+x.status+'\nAgent Used: '+x.agent+'\nExecution ID: '+x.execution_id+(x.error?'\nError: '+x.error:'')).join('\n\n'):'Execution Status: planned\nProject: '+(d.context?.project_name||'Unassigned');}
async function health(){try{const r=await fetch('/rainbow-ai/health.php',{credentials:'same-origin',cache:'no-store'});const d=await r.json();if(!d.ok)throw new Error('Health check failed');badge(adminConnector,d.security.admin_configured?(d.security.authenticated?'Authenticated':'Login Required'):'Not Configured',d.security.authenticated?'ok':(d.security.admin_configured?'warn':'bad'));badge(openaiConnector,d.openai.connected?'Connected':(d.openai.configured?'Configured / Locked':'Not Connected'),d.openai.connected?'ok':(d.openai.configured?'warn':'bad'));if(d.meta&&d.meta.connected){const a=d.meta.account||{};badge(metaConnector,'Connected'+(a.name?' · '+a.name:''),'ok')}else badge(metaConnector,'Not Connected','bad');if(d.whatsapp&&d.whatsapp.connected){const w=d.whatsapp.phone||{};badge(whatsappConnector,'Connected'+(w.verified_name?' · '+w.verified_name:''),'ok')}else badge(whatsappConnector,'Not Connected','bad');if(d.crm&&d.crm.connected){badge(crmConnector,'Connected · '+(d.crm.provider||'CMTS'),'ok')}else if(d.crm&&d.crm.configured){badge(crmConnector,'Configured / Unreachable','warn')}else{badge(crmConnector,'Not Connected','bad')}if(d.openai.connected&&d.meta&&d.meta.connected&&d.whatsapp&&d.whatsapp.connected&&d.crm&&d.crm.connected)setStatus('Business Owner Active · Systems Connected','connected');else setStatus('Connection Check Incomplete','failed')}catch(e){badge(openaiConnector,'Health Check Failed','bad');badge(metaConnector,'Health Check Failed','bad');badge(whatsappConnector,'Health Check Failed','bad');badge(crmConnector,'Health Check Failed','bad');setStatus('Connection Check Failed','failed')}}
const workflowStorageKey='rainbow.activeWorkflow';function savedWorkflow(){try{return JSON.parse(localStorage.getItem(workflowStorageKey)||'null')}catch{return null}}function storeWorkflow(text,w){if(!w)return;localStorage.setItem(workflowStorageKey,JSON.stringify({command:text,workflow:w}))}
function renderTaskTracker(w){if(!w||!Array.isArray(w.tasks)||!w.tasks.length){taskTracker.innerHTML='<div class="task-row">No project progress yet.</div>';return}taskTracker.innerHTML='';w.tasks.forEach((t,i)=>{const explicit=t.status||'';const done=explicit==='completed'||(!explicit&&i<w.completed_steps);const running=explicit==='running'||(!explicit&&i===w.completed_steps&&w.status==='running');const failed=explicit==='failed';const blocked=explicit==='blocked_for_approval';const row=document.createElement('div');row.className='task-row '+(done?'done':running?'running':failed?'failed':blocked?'blocked':'');row.textContent=(done?'✓ ':running?'▶ ':failed?'✕ ':blocked?'! ':'○ ')+(i+1)+'. '+t.agent+' — '+t.task.split('.')[0];taskTracker.appendChild(row)})}
async function executeCommand(text){const saved=savedWorkflow();let workflowId=autoMode.checked&&saved?.command===text?saved.workflow?.workflow_id||'':'';let keepRunning=false;do{const r=await fetch('/rainbow-ai/orchestrate.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({command:text,auto_mode:autoMode.checked,workflow_id:workflowId})});const type=(r.headers.get('content-type')||'').toLowerCase();if(!type.includes('application/json'))throw new Error(r.status===504||r.status===502?'Execution timed out. Auto Mode stopped safely; press Send Command to resume.':'Server returned an invalid response.');const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.message||'Command failed.');renderResult(d);renderTaskTracker(d.auto_workflow);storeWorkflow(text,d.auto_workflow);addHistory(text,d.state);workflowId=d.auto_workflow?.workflow_id||'';keepRunning=autoMode.checked&&d.auto_workflow?.status==='running'&&workflowId!=='';setStatus(keepRunning?'Auto Mode '+d.auto_workflow.completed_steps+'/'+d.auto_workflow.total_steps:'Execution '+d.state,keepRunning?'loading':(d.state==='completed'?'connected':d.state==='blocked_for_approval'?'loading':'failed'));if(keepRunning)await new Promise(resolve=>setTimeout(resolve,800))}while(keepRunning)}
command.addEventListener('input',()=>charCount.textContent=command.value.length+' / 4000');send.addEventListener('click',async()=>{const text=command.value.trim();error('');if(text.length<3){error('Enter a command of at least 3 characters.');return}send.disabled=true;voice.disabled=true;autoMode.disabled=true;send.textContent=autoMode.checked?'Auto Mode Running…':'Executing…';setStatus('Planning and executing…','loading');try{await executeCommand(text)}catch(e){error(e.message||'Command failed.');addHistory(text,'failed');setStatus('Request Failed','failed')}finally{send.disabled=false;voice.disabled=false;autoMode.disabled=false;send.textContent='Send Command'}});
copyOutput.addEventListener('click',async()=>{if(copyOutput.disabled)return;try{await navigator.clipboard.writeText(response.textContent);copyOutput.textContent='Copied';setTimeout(()=>copyOutput.textContent='Copy Output',1200)}catch{error('Could not copy automatically. Select the deliverable text and copy it manually.')}});
continueOutput.addEventListener('click',()=>{if(continueOutput.disabled)return;const project=currentProjectName||'current project';command.value='Continue '+project+' using the latest persisted deliverable as prior context. Execute the next logical internal task now. Do not publish or modify external systems.';command.dispatchEvent(new Event('input'));command.focus();window.scrollTo({top:0,behavior:'smooth'})});
const restored=savedWorkflow();if(restored?.workflow)renderTaskTracker(restored.workflow);const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(SR){voice.addEventListener('click',()=>{const r=new SR();r.lang='en-IN';r.interimResults=false;voice.disabled=true;voice.textContent='Listening…';r.onresult=e=>{command.value=e.results[0][0].transcript;command.dispatchEvent(new Event('input'))};r.onerror=()=>{error('Voice input failed. Check browser microphone permission and try again.')};r.onend=()=>{voice.disabled=false;voice.textContent='Voice Input'};r.start()})}else{voice.disabled=true;voice.textContent='Voice Input unavailable'}health();
</script></body></html>
